/// VADER-style sentiment computation
fn compute_vader_sentiment(s: &str) -> (f64, f64, f64, f64) {
    // Sentiment lexicon with intensity
    let positive_words: Vec<(&str, f64)> = vec![
        ("love", 3.0),
        ("loved", 3.0),
        ("loving", 3.0),
        ("excellent", 3.0),
        ("amazing", 3.0),
        ("fantastic", 3.0),
        ("wonderful", 3.0),
        ("great", 2.5),
        ("awesome", 2.5),
        ("brilliant", 2.5),
        ("superb", 2.5),
        ("good", 2.0),
        ("nice", 2.0),
        ("pleasant", 2.0),
        ("happy", 2.0),
        ("like", 1.5),
        ("enjoy", 1.5),
        ("fine", 1.5),
        ("okay", 1.0),
        ("best", 3.0),
        ("perfect", 3.0),
        ("beautiful", 2.5),
        ("delightful", 2.5),
        ("excited", 2.5),
        ("thrilled", 3.0),
        ("glad", 2.0),
        ("pleased", 2.0),
    ];

    let negative_words: Vec<(&str, f64)> = vec![
        ("hate", 3.0),
        ("hated", 3.0),
        ("hating", 3.0),
        ("terrible", 3.0),
        ("horrible", 3.0),
        ("awful", 3.0),
        ("disgusting", 3.0),
        ("bad", 2.5),
        ("poor", 2.5),
        ("worst", 3.0),
        ("pathetic", 2.5),
        ("sad", 2.0),
        ("angry", 2.5),
        ("upset", 2.0),
        ("disappointed", 2.0),
        ("dislike", 1.5),
        ("annoying", 2.0),
        ("boring", 1.5),
        ("mediocre", 1.0),
        ("ugly", 2.5),
        ("stupid", 2.5),
        ("dumb", 2.0),
        ("useless", 2.5),
        ("painful", 2.5),
        ("miserable", 3.0),
        ("depressing", 2.5),
        ("frustrating", 2.0),
    ];

    // Intensity modifiers
    let boosters = vec![
        "very",
        "really",
        "extremely",
        "absolutely",
        "incredibly",
        "totally",
        "so",
    ];
    let dampeners = vec![
        "somewhat", "slightly", "a bit", "kind of", "sort of", "barely",
    ];

    let lower = s.to_lowercase();
    let words: Vec<&str> = lower.split_whitespace().collect();

    let mut pos_score = 0.0;
    let mut neg_score = 0.0;
    let mut word_count = 0;

    for (i, word) in words.iter().enumerate() {
        let mut modifier = 1.0;

        // Check for boosters/dampeners before this word
        if i > 0 {
            if boosters.contains(&words[i - 1]) {
                modifier = 1.5;
            } else if dampeners.iter().any(|d| words[i - 1].contains(d)) {
                modifier = 0.5;
            }
        }

        // Check for negation
        let negated = i > 0
            && [
                "not",
                "no",
                "never",
                "neither",
                "don't",
                "doesn't",
                "didn't",
                "won't",
                "wouldn't",
                "couldn't",
                "shouldn't",
            ]
            .contains(&words[i - 1]);

        if let Some((_, score)) = positive_words.iter().find(|(w, _)| w == word) {
            if negated {
                neg_score += score * modifier;
            } else {
                pos_score += score * modifier;
            }
            word_count += 1;
        } else if let Some((_, score)) = negative_words.iter().find(|(w, _)| w == word) {
            if negated {
                pos_score += score * modifier * 0.5; // Negated negative is mildly positive
            } else {
                neg_score += score * modifier;
            }
            word_count += 1;
        }
    }

    // Normalize scores
    let total = pos_score + neg_score;
    let (pos_norm, neg_norm) = if total > 0.0 {
        (pos_score / total, neg_score / total)
    } else {
        (0.0, 0.0)
    };

    let neutral = 1.0 - pos_norm - neg_norm;

    // Compound score: normalized to [-1, 1]
    let compound = if word_count > 0 {
        ((pos_score - neg_score) / (word_count as f64 * 3.0))
            .max(-1.0)
            .min(1.0)
    } else {
        0.0
    };

    (pos_norm, neg_norm, neutral.max(0.0), compound)
}

/// Detect specific emotions
fn compute_emotions(s: &str) -> HashMap<String, f64> {
    let emotion_words: Vec<(&str, &str)> = vec![
        // Joy
        ("happy", "joy"),
        ("joyful", "joy"),
        ("delighted", "joy"),
        ("cheerful", "joy"),
        ("excited", "joy"),
        ("thrilled", "joy"),
        ("ecstatic", "joy"),
        ("elated", "joy"),
        // Sadness
        ("sad", "sadness"),
        ("unhappy", "sadness"),
        ("depressed", "sadness"),
        ("miserable", "sadness"),
        ("gloomy", "sadness"),
        ("heartbroken", "sadness"),
        ("sorrowful", "sadness"),
        ("melancholy", "sadness"),
        // Anger
        ("angry", "anger"),
        ("furious", "anger"),
        ("enraged", "anger"),
        ("irritated", "anger"),
        ("annoyed", "anger"),
        ("outraged", "anger"),
        ("livid", "anger"),
        ("mad", "anger"),
        // Fear
        ("afraid", "fear"),
        ("scared", "fear"),
        ("terrified", "fear"),
        ("frightened", "fear"),
        ("anxious", "fear"),
        ("worried", "fear"),
        ("nervous", "fear"),
        ("panicked", "fear"),
        // Surprise
        ("surprised", "surprise"),
        ("amazed", "surprise"),
        ("astonished", "surprise"),
        ("shocked", "surprise"),
        ("stunned", "surprise"),
        ("startled", "surprise"),
        ("bewildered", "surprise"),
        // Disgust
        ("disgusted", "disgust"),
        ("revolted", "disgust"),
        ("repulsed", "disgust"),
        ("sickened", "disgust"),
        ("nauseated", "disgust"),
        ("appalled", "disgust"),
        // Trust
        ("trust", "trust"),
        ("confident", "trust"),
        ("secure", "trust"),
        ("reliable", "trust"),
        ("faithful", "trust"),
        ("loyal", "trust"),
        // Anticipation
        ("eager", "anticipation"),
        ("hopeful", "anticipation"),
        ("expectant", "anticipation"),
        ("looking forward", "anticipation"),
        ("excited", "anticipation"),
    ];

    let lower = s.to_lowercase();
    let mut counts: HashMap<String, f64> = HashMap::new();

    for (word, emotion) in emotion_words {
        if lower.contains(word) {
            *counts.entry(emotion.to_string()).or_insert(0.0) += 1.0;
        }
    }

    // Normalize
    let total: f64 = counts.values().sum();
    if total > 0.0 {
        for v in counts.values_mut() {
            *v /= total;
        }
    }

    counts
}

/// Compute text intensity
fn compute_intensity(s: &str) -> f64 {
    let intensifiers = vec![
        ("very", 1.5),
        ("really", 1.5),
        ("extremely", 2.0),
        ("incredibly", 2.0),
        ("absolutely", 2.0),
        ("totally", 1.5),
        ("completely", 1.5),
        ("utterly", 2.0),
        ("so", 1.3),
        ("such", 1.3),
        ("quite", 1.2),
        ("rather", 1.1),
    ];

    let exclamation_boost = 0.5;
    let caps_boost = 0.3;

    let lower = s.to_lowercase();
    let mut score = 1.0;

    for (word, boost) in intensifiers {
        if lower.contains(word) {
            score *= boost;
        }
    }

    // Check for exclamation marks
    let exclamations = s.matches('!').count();
    score += exclamations as f64 * exclamation_boost;

    // Check for ALL CAPS words
    let caps_words = s
        .split_whitespace()
        .filter(|w| w.len() > 2 && w.chars().all(|c| c.is_uppercase()))
        .count();
    score += caps_words as f64 * caps_boost;

    score.min(5.0)
}

/// Detect sarcasm markers
fn compute_sarcasm_score(s: &str) -> (f64, f64, Vec<String>) {
    let mut markers = Vec::new();
    let mut score: f64 = 0.0;

    let lower = s.to_lowercase();

    // Explicit sarcasm markers
    let explicit = vec![
        "/s",
        "not!",
        "yeah right",
        "sure thing",
        "oh really",
        "oh great",
        "wow, just wow",
        "thanks a lot",
        "how wonderful",
        "isn't that special",
        "clearly",
        "obviously",
        "shocking",
        "no way",
        "what a surprise",
    ];

    for marker in &explicit {
        if lower.contains(marker) {
            markers.push(format!("explicit: {}", marker));
            score += 0.4;
        }
    }

    // Hyperbolic expressions
    let hyperbolic = vec![
        "best thing ever",
        "worst thing ever",
        "literally dying",
        "absolutely perfect",
        "world's greatest",
        "totally awesome",
        "so much fun",
        "couldn't be happier",
    ];

    for h in &hyperbolic {
        if lower.contains(h) {
            markers.push(format!("hyperbole: {}", h));
            score += 0.3;
        }
    }

    // Positive-negative contradiction patterns
    let has_positive = ["great", "wonderful", "amazing", "love", "best", "awesome"]
        .iter()
        .any(|w| lower.contains(w));
    let has_negative_context = ["but", "however", "although", "except", "unfortunately"]
        .iter()
        .any(|w| lower.contains(w));

    if has_positive && has_negative_context {
        markers.push("positive-negative contrast".to_string());
        score += 0.25;
    }

    // Quotation marks around positive words (air quotes)
    let quote_pattern = Regex::new(r#"["'](\w+)["']"#).unwrap();
    for cap in quote_pattern.captures_iter(s) {
        if let Some(m) = cap.get(1) {
            let word = m.as_str().to_lowercase();
            if [
                "great",
                "wonderful",
                "helpful",
                "useful",
                "smart",
                "genius",
                "brilliant",
            ]
            .contains(&word.as_str())
            {
                markers.push(format!("air quotes: \"{}\"", word));
                score += 0.35;
            }
        }
    }

    // Excessive punctuation
    if s.contains("...") || s.contains("!!!") || s.contains("???") {
        markers.push("excessive punctuation".to_string());
        score += 0.15;
    }

    // Calculate confidence based on number of markers
    let confidence = if markers.is_empty() {
        0.0
    } else {
        (markers.len() as f64 * 0.25).min(1.0)
    };

    (score.min(1.0), confidence, markers)
}

/// Detect irony patterns
fn compute_irony_score(s: &str) -> f64 {
    let mut score: f64 = 0.0;
    let lower = s.to_lowercase();

    // Situational irony markers
    let irony_phrases = vec![
        "of course",
        "as expected",
        "naturally",
        "predictably",
        "who would have thought",
        "surprise surprise",
        "go figure",
        "typical",
        "as usual",
        "yet again",
        "once again",
    ];

    for phrase in irony_phrases {
        if lower.contains(phrase) {
            score += 0.2;
        }
    }

    // Contrast indicators
    if lower.contains("but") || lower.contains("yet") || lower.contains("however") {
        score += 0.1;
    }

    // Rhetorical questions
    if s.contains('?')
        && (lower.starts_with("isn't")
            || lower.starts_with("aren't")
            || lower.starts_with("doesn't")
            || lower.starts_with("don't")
            || lower.contains("right?")
            || lower.contains("isn't it"))
    {
        score += 0.25;
    }

    score.min(1.0)
}

/// Create hash-based vector for text
fn create_hash_vector(s: &str, dims: usize) -> Vec<f64> {
    let mut vector = vec![0.0f64; dims];

    for word in s.to_lowercase().split_whitespace() {
        let hash = compute_hash(word, 0);
        let idx = (hash as usize) % dims;
        vector[idx] += 1.0;
    }

    // Normalize
    let magnitude: f64 = vector.iter().map(|x| x * x).sum::<f64>().sqrt();
    if magnitude > 0.0 {
        for v in vector.iter_mut() {
            *v /= magnitude;
        }
    }

    vector
}

/// Count text statistics for readability
fn count_text_stats(s: &str) -> (usize, usize, usize) {
    let words: Vec<&str> = s.split_whitespace().collect();
    let word_count = words.len();
    let sentence_count = s
        .matches(|c| c == '.' || c == '!' || c == '?')
        .count()
        .max(1);

    let mut syllable_count = 0;
    for word in &words {
        syllable_count += count_syllables(word);
    }

    (word_count, sentence_count, syllable_count)
}

/// Count syllables in a word (English approximation)
fn count_syllables(word: &str) -> usize {
    let word = word.to_lowercase();
    let vowels = ['a', 'e', 'i', 'o', 'u', 'y'];
    let mut count = 0;
    let mut prev_was_vowel = false;

    for c in word.chars() {
        let is_vowel = vowels.contains(&c);
        if is_vowel && !prev_was_vowel {
            count += 1;
        }
        prev_was_vowel = is_vowel;
    }

    // Adjust for silent e
    if word.ends_with('e') && count > 1 {
        count -= 1;
    }

    count.max(1)
}

/// Compute American Soundex encoding
fn compute_soundex(s: &str) -> String {
    if s.is_empty() {
        return "0000".to_string();
    }

    let s = s.to_uppercase();
    let chars: Vec<char> = s.chars().filter(|c| c.is_ascii_alphabetic()).collect();

    if chars.is_empty() {
        return "0000".to_string();
    }

    let first = chars[0];
    let mut code = String::new();
    code.push(first);

    let get_code = |c: char| -> char {
        match c {
            'B' | 'F' | 'P' | 'V' => '1',
            'C' | 'G' | 'J' | 'K' | 'Q' | 'S' | 'X' | 'Z' => '2',
            'D' | 'T' => '3',
            'L' => '4',
            'M' | 'N' => '5',
            'R' => '6',
            _ => '0',
        }
    };

    let mut prev_code = get_code(first);

    for &c in chars.iter().skip(1) {
        let curr_code = get_code(c);
        if curr_code != '0' && curr_code != prev_code {
            code.push(curr_code);
            if code.len() == 4 {
                break;
            }
        }
        prev_code = curr_code;
    }

    while code.len() < 4 {
        code.push('0');
    }

    code
}

/// Compute Metaphone encoding
fn compute_metaphone(s: &str) -> String {
    let s = s.to_uppercase();
    let chars: Vec<char> = s.chars().filter(|c| c.is_ascii_alphabetic()).collect();

    if chars.is_empty() {
        return String::new();
    }

    let mut result = String::new();
    let mut i = 0;

    // Skip initial KN, GN, PN, AE, WR
    if chars.len() >= 2 {
        let prefix: String = chars[0..2].iter().collect();
        if ["KN", "GN", "PN", "AE", "WR"].contains(&prefix.as_str()) {
            i = 1;
        }
    }

    while i < chars.len() && result.len() < 6 {
        let c = chars[i];
        let prev = if i > 0 { Some(chars[i - 1]) } else { None };
        let next = chars.get(i + 1).copied();

        let code = match c {
            'A' | 'E' | 'I' | 'O' | 'U' => {
                if i == 0 {
                    Some(c)
                } else {
                    None
                }
            }
            'B' => {
                if prev != Some('M') || i == chars.len() - 1 {
                    Some('B')
                } else {
                    None
                }
            }
            'C' => {
                if next == Some('H') {
                    Some('X')
                } else if matches!(next, Some('I') | Some('E') | Some('Y')) {
                    Some('S')
                } else {
                    Some('K')
                }
            }
            'D' => {
                if next == Some('G')
                    && matches!(chars.get(i + 2), Some('E') | Some('I') | Some('Y'))
                {
                    Some('J')
                } else {
                    Some('T')
                }
            }
            'F' => Some('F'),
            'G' => {
                if next == Some('H')
                    && !matches!(
                        chars.get(i + 2),
                        Some('A') | Some('E') | Some('I') | Some('O') | Some('U')
                    )
                {
                    None
                } else if matches!(next, Some('N') | Some('E') | Some('I') | Some('Y')) {
                    Some('J')
                } else {
                    Some('K')
                }
            }
            'H' => {
                if matches!(
                    prev,
                    Some('A') | Some('E') | Some('I') | Some('O') | Some('U')
                ) {
                    None
                } else if matches!(
                    next,
                    Some('A') | Some('E') | Some('I') | Some('O') | Some('U')
                ) {
                    Some('H')
                } else {
                    None
                }
            }
            'J' => Some('J'),
            'K' => {
                if prev != Some('C') {
                    Some('K')
                } else {
                    None
                }
            }
            'L' => Some('L'),
            'M' => Some('M'),
            'N' => Some('N'),
            'P' => {
                if next == Some('H') {
                    Some('F')
                } else {
                    Some('P')
                }
            }
            'Q' => Some('K'),
            'R' => Some('R'),
            'S' => {
                if next == Some('H') {
                    Some('X')
                } else {
                    Some('S')
                }
            }
            'T' => {
                if next == Some('H') {
                    Some('0') // TH sound
                } else if next == Some('I') && matches!(chars.get(i + 2), Some('O') | Some('A')) {
                    Some('X')
                } else {
                    Some('T')
                }
            }
            'V' => Some('F'),
            'W' | 'Y' => {
                if matches!(
                    next,
                    Some('A') | Some('E') | Some('I') | Some('O') | Some('U')
                ) {
                    Some(c)
                } else {
                    None
                }
            }
            'X' => {
                result.push('K');
                Some('S')
            }
            'Z' => Some('S'),
            _ => None,
        };

        if let Some(ch) = code {
            result.push(ch);
        }

        // Skip double letters
        if next == Some(c) {
            i += 1;
        }
        i += 1;
    }

    result
}

/// Compute Cologne phonetic encoding (for German)
fn compute_cologne(s: &str) -> String {
    let s = s.to_uppercase();
    let chars: Vec<char> = s.chars().filter(|c| c.is_ascii_alphabetic()).collect();

    if chars.is_empty() {
        return String::new();
    }

    let mut result = String::new();

    for (i, &c) in chars.iter().enumerate() {
        let prev = if i > 0 { Some(chars[i - 1]) } else { None };
        let next = chars.get(i + 1).copied();

        let code = match c {
            'A' | 'E' | 'I' | 'O' | 'U' | 'J' | 'Y' => '0',
            'H' => continue,
            'B' | 'P' => '1',
            'D' | 'T' => {
                if matches!(next, Some('C') | Some('S') | Some('Z')) {
                    '8'
                } else {
                    '2'
                }
            }
            'F' | 'V' | 'W' => '3',
            'G' | 'K' | 'Q' => '4',
            'C' => {
                if i == 0 {
                    if matches!(
                        next,
                        Some('A')
                            | Some('H')
                            | Some('K')
                            | Some('L')
                            | Some('O')
                            | Some('Q')
                            | Some('R')
                            | Some('U')
                            | Some('X')
                    ) {
                        '4'
                    } else {
                        '8'
                    }
                } else if matches!(prev, Some('S') | Some('Z')) {
                    '8'
                } else if matches!(
                    next,
                    Some('A')
                        | Some('H')
                        | Some('K')
                        | Some('O')
                        | Some('Q')
                        | Some('U')
                        | Some('X')
                ) {
                    '4'
                } else {
                    '8'
                }
            }
            'X' => {
                if matches!(prev, Some('C') | Some('K') | Some('Q')) {
                    '8'
                } else {
                    result.push('4');
                    '8'
                }
            }
            'L' => '5',
            'M' | 'N' => '6',
            'R' => '7',
            'S' | 'Z' => '8',
            _ => continue,
        };

        result.push(code);
    }

    // Remove consecutive duplicates
    let mut deduped = String::new();
    let mut prev = None;
    for c in result.chars() {
        if prev != Some(c) {
            deduped.push(c);
        }
        prev = Some(c);
    }

    // Remove leading zeros (except if all zeros)
    let trimmed: String = deduped.trim_start_matches('0').to_string();
    if trimmed.is_empty() {
        "0".to_string()
    } else {
        trimmed
    }
}

