    // ========== GRAPHICS MATH TESTS ==========

    #[test]
    fn test_quaternion_identity() {
        let result = eval("rite main() { ≔ q = quat_identity(); ⤺ q; }");
        if let Ok(Value::Array(arr)) = result {
            let arr = arr.borrow();
            assert_eq!(arr.len(), 4);
            if let (Value::Float(w), Value::Float(x), Value::Float(y), Value::Float(z)) =
                (&arr[0], &arr[1], &arr[2], &arr[3])
            {
                assert!((w - 1.0).abs() < 0.001);
                assert!(x.abs() < 0.001);
                assert!(y.abs() < 0.001);
                assert!(z.abs() < 0.001);
            }
        } else {
            panic!("Expected quaternion array");
        }
    }

    #[test]
    fn test_quaternion_from_axis_angle() {
        // 90 degrees around Y axis
        let result =
            eval("rite main() { ≔ q = quat_from_axis_angle(vec3(0, 1, 0), 1.5707963); ⤺ q; }");
        if let Ok(Value::Array(arr)) = result {
            let arr = arr.borrow();
            assert_eq!(arr.len(), 4);
            // Should be approximately [cos(45°), 0, sin(45°), 0] = [0.707, 0, 0.707, 0]
            if let (Value::Float(w), Value::Float(x), Value::Float(y), Value::Float(z)) =
                (&arr[0], &arr[1], &arr[2], &arr[3])
            {
                assert!((w - 0.707).abs() < 0.01, "w={}", w);
                assert!(x.abs() < 0.01);
                assert!((y - 0.707).abs() < 0.01, "y={}", y);
                assert!(z.abs() < 0.01);
            }
        } else {
            panic!("Expected quaternion array");
        }
    }

    #[test]
    fn test_quaternion_rotate_vector() {
        // Rotate [1, 0, 0] by 90 degrees around Z axis should give [0, 1, 0]
        let result = eval(
            r#"
            rite main() {
                ≔ q = quat_from_axis_angle(vec3(0, 0, 1), 1.5707963);
                ≔ v = vec3(1, 0, 0);
                ⤺ quat_rotate(q, v);
            }
        "#,
        );
        if let Ok(Value::Array(arr)) = result {
            let arr = arr.borrow();
            assert_eq!(arr.len(), 3);
            if let (Value::Float(x), Value::Float(y), Value::Float(z)) = (&arr[0], &arr[1], &arr[2])
            {
                assert!(x.abs() < 0.01, "x={}", x);
                assert!((y - 1.0).abs() < 0.01, "y={}", y);
                assert!(z.abs() < 0.01);
            }
        } else {
            panic!("Expected vec3 array");
        }
    }

    #[test]
    fn test_quaternion_slerp() {
        // Interpolate between identity and 90° rotation
        let result = eval(
            r#"
            rite main() {
                ≔ q1 = quat_identity();
                ≔ q2 = quat_from_axis_angle(vec3(0, 1, 0), 1.5707963);
                ⤺ quat_slerp(q1, q2, 0.5);
            }
        "#,
        );
        if let Ok(Value::Array(arr)) = result {
            let arr = arr.borrow();
            assert_eq!(arr.len(), 4);
            // At t=0.5, should be 45° rotation
            if let Value::Float(w) = &arr[0] {
                // cos(22.5°) ≈ 0.924
                assert!((w - 0.924).abs() < 0.05, "w={}", w);
            }
        } else {
            panic!("Expected quaternion array");
        }
    }

    #[test]
    fn test_vec3_operations() {
        // vec3_add
        let result = eval("rite main() { ⤺ vec3_add(vec3(1, 2, 3), vec3(4, 5, 6)); }");
        if let Ok(Value::Array(arr)) = result {
            let arr = arr.borrow();
            if let (Value::Float(x), Value::Float(y), Value::Float(z)) = (&arr[0], &arr[1], &arr[2])
            {
                assert!((x - 5.0).abs() < 0.001);
                assert!((y - 7.0).abs() < 0.001);
                assert!((z - 9.0).abs() < 0.001);
            }
        }

        // vec3_dot
        let result = eval("rite main() { ⤺ vec3_dot(vec3(1, 2, 3), vec3(4, 5, 6)); }");
        assert!(matches!(result, Ok(Value::Float(f)) if (f - 32.0).abs() < 0.001));

        // vec3_cross
        let result = eval("rite main() { ⤺ vec3_cross(vec3(1, 0, 0), vec3(0, 1, 0)); }");
        if let Ok(Value::Array(arr)) = result {
            let arr = arr.borrow();
            if let (Value::Float(x), Value::Float(y), Value::Float(z)) = (&arr[0], &arr[1], &arr[2])
            {
                assert!(x.abs() < 0.001);
                assert!(y.abs() < 0.001);
                assert!((z - 1.0).abs() < 0.001);
            }
        }

        // vec3_length
        let result = eval("rite main() { ⤺ vec3_length(vec3(3, 4, 0)); }");
        assert!(matches!(result, Ok(Value::Float(f)) if (f - 5.0).abs() < 0.001));

        // vec3_normalize
        let result = eval("rite main() { ⤺ vec3_normalize(vec3(3, 0, 0)); }");
        if let Ok(Value::Array(arr)) = result {
            let arr = arr.borrow();
            if let Value::Float(x) = &arr[0] {
                assert!((x - 1.0).abs() < 0.001);
            }
        }
    }

    #[test]
