    #[test]
    fn test_channel_high_throughput() {
        // Test sending 1000 messages through a channel
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ ch = channel_new();
                ≔ count = 1000;
                ≔ Δ i = 0;
                ⟳ i < count {
                    channel_send(ch, i);
                    i = i + 1;
                }

                // Receive all and compute sum to verify no data loss
                ≔ Δ sum = 0;
                ≔ Δ j = 0;
                ⟳ j < count {
                    ≔ val = channel_recv(ch);
                    sum = sum + val;
                    j = j + 1;
                }

                // Sum of 0..999 = 499500
                ⤺ sum;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(499500))));
    }

