    // --- GEOMETRIC ALGEBRA PROPERTY TESTS ---

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(50))]

        #[test]
        fn test_ga_bivector_anticommutative(x1 in -100.0f64..100.0, y1 in -100.0f64..100.0, z1 in -100.0f64..100.0,
                                            x2 in -100.0f64..100.0, y2 in -100.0f64..100.0, z2 in -100.0f64..100.0) {
            // e_i ^ e_j = -e_j ^ e_i (bivector anticommutativity)
            // Test via wedge product: a ^ b = -(b ^ a)
            let code = format!(r#"
                rite main() {{
                    ≔ a = vec3({}, {}, {});
                    ≔ b = vec3({}, {}, {});
                    ≔ ab = vec3_cross(a, b);
                    ≔ ba = vec3_cross(b, a);
                    ≔ diff_x = get(ab, 0) + get(ba, 0);
                    ≔ diff_y = get(ab, 1) + get(ba, 1);
                    ≔ diff_z = get(ab, 2) + get(ba, 2);
                    ≔ eps = 0.001;
                    ⤺ eps > abs(diff_x) && eps > abs(diff_y) && eps > abs(diff_z);
                }}
            "#, x1, y1, z1, x2, y2, z2);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_vec3_dot_commutative(x1 in -100.0f64..100.0, y1 in -100.0f64..100.0, z1 in -100.0f64..100.0,
                                     x2 in -100.0f64..100.0, y2 in -100.0f64..100.0, z2 in -100.0f64..100.0) {
            // a · b = b · a (dot product commutativity)
            let code = format!(r#"
                rite main() {{
                    ≔ a = vec3({}, {}, {});
                    ≔ b = vec3({}, {}, {});
                    ≔ ab = vec3_dot(a, b);
                    ≔ ba = vec3_dot(b, a);
                    ≔ eps = 0.001;
                    ⤺ eps > abs(ab - ba);
                }}
            "#, x1, y1, z1, x2, y2, z2);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_quat_identity_preserves_vector(x in -100.0f64..100.0, y in -100.0f64..100.0, z in -100.0f64..100.0) {
            // Rotating by identity quaternion should preserve the vector
            let code = format!(r#"
                rite main() {{
                    ≔ v = vec3({}, {}, {});
                    ≔ q = quat_identity();
                    ≔ rotated = quat_rotate(q, v);
                    ≔ diff_x = abs(get(v, 0) - get(rotated, 0));
                    ≔ diff_y = abs(get(v, 1) - get(rotated, 1));
                    ≔ diff_z = abs(get(v, 2) - get(rotated, 2));
                    ≔ eps = 0.001;
                    ⤺ eps > diff_x && eps > diff_y && eps > diff_z;
                }}
            "#, x, y, z);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_quat_double_rotation_equals_double_angle(x in -100.0f64..100.0, y in -100.0f64..100.0, z in -100.0f64..100.0,
                                                          angle in -3.14f64..3.14) {
            // q(2θ) should equal q(θ) * q(θ)
            let code = format!(r#"
                rite main() {{
                    ≔ v = vec3({}, {}, {});
                    ≔ axis = vec3(0.0, 1.0, 0.0);
                    ≔ q1 = quat_from_axis_angle(axis, {});
                    ≔ q2 = quat_from_axis_angle(axis, {} * 2.0);
                    ≔ q1q1 = quat_mul(q1, q1);
                    ≔ eps = 0.01;
                    ≔ same = eps > abs(get(q2, 0) - get(q1q1, 0)) &&
                               eps > abs(get(q2, 1) - get(q1q1, 1)) &&
                               eps > abs(get(q2, 2) - get(q1q1, 2)) &&
                               eps > abs(get(q2, 3) - get(q1q1, 3));
                    ≔ neg_same = eps > abs(get(q2, 0) + get(q1q1, 0)) &&
                                   eps > abs(get(q2, 1) + get(q1q1, 1)) &&
                                   eps > abs(get(q2, 2) + get(q1q1, 2)) &&
                                   eps > abs(get(q2, 3) + get(q1q1, 3));
                    ⤺ same || neg_same;
                }}
            "#, x, y, z, angle, angle);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_vec3_add_associative(x1 in -100.0f64..100.0, y1 in -100.0f64..100.0, z1 in -100.0f64..100.0,
                                     x2 in -100.0f64..100.0, y2 in -100.0f64..100.0, z2 in -100.0f64..100.0,
                                     x3 in -100.0f64..100.0, y3 in -100.0f64..100.0, z3 in -100.0f64..100.0) {
            // (a + b) + c = a + (b + c)
            let code = format!(r#"
                rite main() {{
                    ≔ a = vec3({}, {}, {});
                    ≔ b = vec3({}, {}, {});
                    ≔ c = vec3({}, {}, {});
                    ≔ ab_c = vec3_add(vec3_add(a, b), c);
                    ≔ a_bc = vec3_add(a, vec3_add(b, c));
                    ≔ diff_x = abs(get(ab_c, 0) - get(a_bc, 0));
                    ≔ diff_y = abs(get(ab_c, 1) - get(a_bc, 1));
                    ≔ diff_z = abs(get(ab_c, 2) - get(a_bc, 2));
                    ≔ eps = 0.001;
                    ⤺ eps > diff_x && eps > diff_y && eps > diff_z;
                }}
            "#, x1, y1, z1, x2, y2, z2, x3, y3, z3);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_vec3_scale_distributive(x in -100.0f64..100.0, y in -100.0f64..100.0, z in -100.0f64..100.0,
                                        s1 in -10.0f64..10.0, s2 in -10.0f64..10.0) {
            // (s1 + s2) * v = s1*v + s2*v
            let code = format!(r#"
                rite main() {{
                    ≔ v = vec3({}, {}, {});
                    ≔ s1 = {};
                    ≔ s2 = {};
                    ≔ combined = vec3_scale(v, s1 + s2);
                    ≔ separate = vec3_add(vec3_scale(v, s1), vec3_scale(v, s2));
                    ≔ diff_x = abs(get(combined, 0) - get(separate, 0));
                    ≔ diff_y = abs(get(combined, 1) - get(separate, 1));
                    ≔ diff_z = abs(get(combined, 2) - get(separate, 2));
                    ≔ eps = 0.01;
                    ⤺ eps > diff_x && eps > diff_y && eps > diff_z;
                }}
            "#, x, y, z, s1, s2);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }
    }

    // --- AUTODIFF PROPERTY TESTS ---

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(30))]

        #[test]
        fn test_grad_of_constant_is_zero(c in -100.0f64..100.0, x in -100.0f64..100.0) {
            // d/dx(c) = 0
            let code = format!(r#"
                rite main() -> bool {{
                    rite constant(x) -> f64 {{ ⤺ {}; }}
                    ≔ g = grad(constant, {});
                    ≔ eps = 0.001;
                    ⤺ eps > abs(g);
                }}
            "#, c, x);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_grad_of_x_is_one(x in -100.0f64..100.0) {
            // d/dx(x) = 1
            let code = format!(r#"
                rite main() -> bool {{
                    rite identity(x) -> f64 {{ ⤺ x; }}
                    ≔ g = grad(identity, {});
                    ≔ eps = 0.001;
                    ⤺ eps > abs(g - 1.0);
                }}
            "#, x);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_grad_of_x_squared(x in -50.0f64..50.0) {
            // d/dx(x^2) = 2x
            let code = format!(r#"
                rite main() -> bool {{
                    rite square(x) -> f64 {{ ⤺ x * x; }}
                    ≔ g = grad(square, {});
                    ≔ expected = 2.0 * {};
                    ≔ eps = 0.1;
                    ⤺ eps > abs(g - expected);
                }}
            "#, x, x);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_grad_linearity(a in -10.0f64..10.0, b in -10.0f64..10.0, x in -10.0f64..10.0) {
            // d/dx(a*x + b) = a
            // Note: 'linear' is a reserved keyword in Sigil, so use 'lin_fn' instead
            let code = format!(r#"
                rite main() -> bool {{
                    rite lin_fn(x) -> f64 {{ ⤺ {} * x + {}; }}
                    ≔ g = grad(lin_fn, {});
                    ≔ eps = 0.1;
                    ⤺ eps > abs(g - {});
                }}
            "#, a, b, x, a);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }
    }

    // --- ARITHMETIC PROPERTY TESTS ---

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(50))]

        #[test]
        fn test_addition_commutative(a in -1000i64..1000, b in -1000i64..1000) {
            let code = format!("rite main() -> bool {{ ⤺ {} + {} == {} + {}; }}", a, b, b, a);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_multiplication_commutative(a in -100i64..100, b in -100i64..100) {
            let code = format!("rite main() -> bool {{ ⤺ {} * {} == {} * {}; }}", a, b, b, a);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_addition_identity(a in -1000i64..1000) {
            let code = format!("rite main() -> bool {{ ⤺ {} + 0 == {}; }}", a, a);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_multiplication_identity(a in -1000i64..1000) {
            let code = format!("rite main() -> bool {{ ⤺ {} * 1 == {}; }}", a, a);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_distributive_property(a in -20i64..20, b in -20i64..20, c in -20i64..20) {
            let code = format!("rite main() -> bool {{ ⤺ {} * ({} + {}) == {} * {} + {} * {}; }}", a, b, c, a, b, a, c);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }
    }

    // --- COLLECTION PROPERTY TESTS ---

    proptest! {
        #![proptest_config(ProptestConfig::with_cases(30))]

        #[test]
        fn test_array_len_after_push(initial_len in 0..20usize, value in -100i64..100) {
            let initial: String = (0..initial_len).map(|i| format!("{}", i)).collect::<Vec<_>>().join(", ");
            let code = format!(r#"
                rite main() -> i64 {{
                    ≔ arr = [{}];
                    push(arr, {});
                    ⤺ len(arr);
                }}
            "#, initial, value);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Int(n)) if n == (initial_len + 1) as i64));
        }

        #[test]
        fn test_reverse_reverse_identity(elements in prop::collection::vec(-100i64..100, 0..10)) {
            let arr_str = elements.iter().map(|n| n.to_string()).collect::<Vec<_>>().join(", ");
            let code = format!(r#"
                rite main() -> bool {{
                    ≔ arr = [{}];
                    ≔ rev1 = reverse(arr);
                    ≔ rev2 = reverse(rev1);
                    ≔ Δ same = true;
                    ≔ Δ i = 0;
                    ⟳ i < len(arr) {{
                        ⎇ get(arr, i) != get(rev2, i) {{
                            same = false;
                        }}
                        i = i + 1;
                    }}
                    ⤺ same;
                }}
            "#, arr_str);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Bool(true))));
        }

        #[test]
        fn test_sum_equals_manual_sum(elements in prop::collection::vec(-100i64..100, 0..20)) {
            let arr_str = elements.iter().map(|n| n.to_string()).collect::<Vec<_>>().join(", ");
            let expected_sum: i64 = elements.iter().sum();
            let code = format!("rite main() -> i64 {{ ⤺ sum([{}]); }}", arr_str);
            let result = eval(&code);
            assert!(matches!(result, Ok(Value::Int(n)) if n == expected_sum));
        }
    }

    // ============================================================================
    // MEMORY LEAK TESTS
    // These tests verify that repeated operations don't cause memory leaks.
    // They run operations many times and check that the interpreter completes
    // without running out of memory or panicking.
    // ============================================================================

    #[test]
    fn test_no_leak_repeated_array_operations() {
        // Create and discard arrays many times
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ Δ i = 0;
                ⟳ i < 1000 {
                    ≔ arr = [1, 2, 3, 4, 5];
                    push(arr, 6);
                    ≔ rev = reverse(arr);
                    ≔ s = sum(arr);
                    i = i + 1;
                }
                ⤺ i;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(1000))));
    }

    #[test]
    fn test_no_leak_repeated_function_calls() {
        // Call functions many times to test function frame cleanup
        let result = eval(
            r#"
            rite fib(n) -> i64 {
                ⎇ n <= 1 { ⤺ n; }
                ⤺ fib(n - 1) + fib(n - 2);
            }
            rite main() -> i64 {
                ≔ Δ i = 0;
                ≔ Δ total = 0;
                ⟳ i < 100 {
                    total = total + fib(10);
                    i = i + 1;
                }
                ⤺ total;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(5500))));
    }

    #[test]
    fn test_no_leak_repeated_map_operations() {
        // Create and discard maps many times
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ Δ i = 0;
                ⟳ i < 500 {
                    ≔ m = map_new();
                    map_set(m, "key1", 1);
                    map_set(m, "key2", 2);
                    map_set(m, "key3", 3);
                    ≔ v = map_get(m, "key1");
                    i = i + 1;
                }
                ⤺ i;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(500))));
    }

    #[test]
    fn test_no_leak_repeated_string_operations() {
        // Create and discard strings many times
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ Δ i = 0;
                ⟳ i < 1000 {
                    ≔ s = "hello world";
                    ≔ upper_s = upper(s);
                    ≔ lower_s = lower(upper_s);
                    ≔ concat_s = s ++ " " ++ upper_s;
                    ≔ replaced = replace(concat_s, "o", "0");
                    i = i + 1;
                }
                ⤺ i;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(1000))));
    }

    #[test]
    fn test_no_leak_repeated_ecs_operations() {
        // Create and discard ECS entities many times
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ world = ecs_world();
                ≔ Δ i = 0;
                ⟳ i < 500 {
                    ≔ entity = ecs_spawn(world);
                    ecs_attach(world, entity, "Position", vec3(1.0, 2.0, 3.0));
                    ecs_attach(world, entity, "Velocity", vec3(0.0, 0.0, 0.0));
                    ≔ pos = ecs_get(world, entity, "Position");
                    i = i + 1;
                }
                ⤺ i;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(500))));
    }

    #[test]
    fn test_no_leak_repeated_channel_operations() {
        // Create and use channels many times
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ Δ i = 0;
                ⟳ i < 500 {
                    ≔ ch = channel_new();
                    channel_send(ch, i);
                    channel_send(ch, i + 1);
                    ≔ v1 = channel_recv(ch);
                    ≔ v2 = channel_recv(ch);
                    i = i + 1;
                }
                ⤺ i;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(500))));
    }

    #[test]
    fn test_no_leak_repeated_actor_operations() {
        // Create actors and send messages many times
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ Δ i = 0;
                ⟳ i < 100 {
                    ≔ act = spawn_actor("leak_test_actor");
                    send_to_actor(act, "msg", i);
                    send_to_actor(act, "msg", i + 1);
                    ≔ count = get_actor_msg_count(act);
                    i = i + 1;
                }
                ⤺ i;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(100))));
    }

    #[test]
    fn test_no_leak_repeated_vec3_operations() {
        // Create and compute with vec3s many times
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ Δ i = 0;
                ⟳ i < 1000 {
                    ≔ v1 = vec3(1.0, 2.0, 3.0);
                    ≔ v2 = vec3(4.0, 5.0, 6.0);
                    ≔ added = vec3_add(v1, v2);
                    ≔ scaled = vec3_scale(added, 2.0);
                    ≔ dot = vec3_dot(v1, v2);
                    ≔ crossed = vec3_cross(v1, v2);
                    ≔ normalized = vec3_normalize(crossed);
                    i = i + 1;
                }
                ⤺ i;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(1000))));
    }

    #[test]
    fn test_no_leak_repeated_closure_creation() {
        // Create and call closures many times
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ Δ i = 0;
                ≔ Δ total = 0;
                ⟳ i < 500 {
                    ≔ x = i;
                    rite add_x(y) -> i64 { ⤺ x + y; }
                    total = total + add_x(1);
                    i = i + 1;
                }
                ⤺ total;
            }
        "#,
        );
        // Sum of (i+1) for i from 0 to 499 = sum of 1 to 500 = 500*501/2 = 125250
        assert!(matches!(result, Ok(Value::Int(125250))));
    }

    #[test]
    fn test_no_leak_nested_data_structures() {
        // Create nested arrays and maps many times
        let result = eval(
            r#"
            rite main() -> i64 {
                ≔ Δ i = 0;
                ⟳ i < 200 {
                    ≔ inner1 = [1, 2, 3];
                    ≔ inner2 = [4, 5, 6];
                    ≔ outer = [inner1, inner2];
                    ≔ m = map_new();
                    map_set(m, "arr", outer);
                    map_set(m, "nested", map_new());
                    i = i + 1;
                }
                ⤺ i;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(200))));
    }

    #[test]
    fn test_no_leak_repeated_interpreter_creation() {
        // This tests at the Rust level - creating multiple interpreters
        for _ in 0..50 {
            let result = eval(
                r#"
                rite main() -> i64 {
                    ≔ arr = [1, 2, 3, 4, 5];
                    ≔ total = sum(arr);
                    ⤺ total * 2;
                }
            "#,
            );
            assert!(matches!(result, Ok(Value::Int(30))));
        }
    }

    // ========== SGDOC TESTS ==========

    #[test]
    fn test_sgdoc_claim_verified() {
        let result = eval(
            r#"
            rite main() {
                ≔ claim = Claim·verified("Test claim", "test.sg");
                ⤺ Claim·is_verified(claim);
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Bool(true))));
    }

    #[test]
    fn test_sgdoc_claim_shorthand() {
        let result = eval(
            r#"
            rite main() {
                ≔ v = Claim·v("Verified");
                ≔ r = Claim·r("Reported");
                ≔ u = Claim·u("Uncertain");
                ≔ p = Claim·p("Predicted");
                ⤺ Claim·is_verified(v);
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Bool(true))));
    }

    #[test]
    fn test_sgdoc_claim_not_verified() {
        let result = eval(
            r#"
            rite main() {
                ≔ claim = Claim·uncertain("Needs investigation");
                ⤺ Claim·is_verified(claim);
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Bool(false))));
    }

    #[test]
    fn test_sgdoc_claim_promote() {
        let result = eval(
            r#"
            rite main() {
                ≔ claim = Claim·uncertain("Was uncertain");
                ≔ promoted = Claim·promote(claim, "test.sg");
                ⤺ Claim·is_verified(promoted);
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Bool(true))));
    }

    #[test]
    fn test_sgdoc_claim_demote() {
        let result = eval(
            r#"
            rite main() {
                ≔ claim = Claim·verified("Was verified", "test.sg");
                ≔ demoted = Claim·demote(claim);
                ⤺ Claim·is_verified(demoted);
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Bool(false))));
    }

    #[test]
    fn test_sgdoc_doc_new() {
        let result = eval(
            r#"
            rite main() {
                ≔ meta = DocMeta·new("Test", 0, 4, 0);
                ≔ doc = Doc·new(meta, "Summary");
                ⤺ 1;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(1))));
    }

    #[test]
    fn test_sgdoc_section_add_claim() {
        let result = eval(
            r#"
            rite main() {
                ≔ claim = Claim·v("Test");
                ≔ Δ section = Section·new("1", "First");
                section = Section·add_claim(section, claim);
                ⤺ 1;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(1))));
    }

    #[test]
    fn test_sgdoc_doc_verify() {
        let result = eval(
            r#"
            rite main() {
                ≔ meta = DocMeta·new("Test", 0, 4, 0);
                ≔ Δ doc = Doc·new(meta, "Summary");
                ≔ Δ section = Section·new("1", "Section");
                section = Section·add_claim(section, Claim·v("Verified"));
                section = Section·add_claim(section, Claim·r("Reported"));
                doc = Doc·add_section(doc, section);
                ≔ report = Doc·verify(doc);
                ⤺ 1;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(1))));
    }

    #[test]
    fn test_sgdoc_doc_unverified_claims() {
        let result = eval(
            r#"
            rite main() {
                ≔ meta = DocMeta·new("Test", 0, 4, 0);
                ≔ Δ doc = Doc·new(meta, "Summary");
                ≔ Δ section = Section·new("1", "Section");
                section = Section·add_claim(section, Claim·v("Verified"));
                section = Section·add_claim(section, Claim·r("Reported"));
                section = Section·add_claim(section, Claim·u("Uncertain"));
                doc = Doc·add_section(doc, section);
                ≔ unverified = Doc·unverified_claims(doc);
                ⤺ len(unverified);
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(2))));
    }

    #[test]
    fn test_sgdoc_example_verify() {
        let result = eval(
            r#"
            rite main() {
                ≔ ex = Example·new("Test", "code", "output");
                ≔ verified = Example·verify(ex);
                ⤺ 1;
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Int(1))));
    }

    #[test]
    fn test_sgdoc_to_markdown() {
        let result = eval(
            r#"
            rite main() {
                ≔ meta = DocMeta·new("Test", 0, 4, 0);
                ≔ Δ doc = Doc·new(meta, "Summary");
                ≔ Δ section = Section·new("1", "Section");
                section = Section·add_claim(section, Claim·v("Verified claim"));
                doc = Doc·add_section(doc, section);
                ≔ md = Doc·to_markdown(doc);
                ⤺ contains(md, "Test");
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Bool(true))));
    }

    #[test]
    fn test_sgdoc_to_html() {
        let result = eval(
            r#"
            rite main() {
                ≔ meta = DocMeta·new("Test", 0, 4, 0);
                ≔ Δ doc = Doc·new(meta, "Summary");
                ≔ Δ section = Section·new("1", "Section");
                section = Section·add_claim(section, Claim·v("Verified claim"));
                doc = Doc·add_section(doc, section);
                ≔ html = Doc·to_html(doc);
                ⤺ contains(html, "<html");
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Bool(true))));
    }

    #[test]
    fn test_sgdoc_to_json() {
        let result = eval(
            r#"
            rite main() {
                ≔ meta = DocMeta·new("Test", 0, 4, 0);
                ≔ doc = Doc·new(meta, "Summary");
                ≔ json = Doc·to_json(doc);
                ⤺ contains(json, "Doc");
            }
        "#,
        );
        assert!(matches!(result, Ok(Value::Bool(true))));
    }
